import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws synchronously naming the tool when registering an invalid static inputSchema', () => {
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {count: {type: 'unknown_type'}}};

    expect(() =>
      registry.register({name: 'broken_counter', description: 'Counts items', inputSchema: schema}, async () => '0')
    ).toThrow(/broken_counter/);
  });

  it('reuses the static validator across repeated execute calls without re-reading inputSchema', async () => {
    let schemaReads = 0;
    const schema = {type: 'object', properties: {location: {type: 'string'}}};
    const definition = {
      name: 'get_weather',
      description: 'Get weather',
      get inputSchema() {
        schemaReads += 1;
        return schema;
      },
    };
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(definition, async () => {
      executorCalls += 1;
      return 'sunny';
    });
    const readsAtRegister = schemaReads;

    for (let i = 0; i < 10; i += 1) {
      await registry.execute('get_weather', {location: 'Paris'});
    }

    expect({readsAtRegister, schemaReads, executorCalls}).toEqual({
      readsAtRegister: 1,
      schemaReads: 1,
      executorCalls: 10,
    });
  });

  it('caches compiled validators by schema reference for function-valued tool sources', async () => {
    const trackedA = trackedSchema({city: {type: 'string'}});
    const trackedB = trackedSchema({zip: {type: 'string'}});
    let sourceCalls = 0;
    let currentSchema = trackedA.schema;

    const registry = new ToolRegistry();
    registry.register(
      () => {
        sourceCalls += 1;
        return {
          name: 'dynamic_weather',
          description: 'Dynamic weather tool',
          inputSchema: currentSchema,
        };
      },
      async () => 'ok'
    );
    const callsAtRegister = sourceCalls;

    await registry.execute('dynamic_weather', {city: 'Paris'});
    const readsAAfterFirst = trackedA.getCompileReads();
    await registry.execute('dynamic_weather', {city: 'Lyon'});
    const readsAAfterSecond = trackedA.getCompileReads();
    currentSchema = trackedB.schema;
    await registry.execute('dynamic_weather', {zip: '75001'});

    expect({
      callsDuringExecute: sourceCalls - callsAtRegister,
      firstCompiledA: readsAAfterFirst > 0,
      reusedCachedA: readsAAfterSecond === readsAAfterFirst,
      compiledB: trackedB.getCompileReads() > 0,
    }).toEqual({
      callsDuringExecute: 3,
      firstCompiledA: true,
      reusedCachedA: true,
      compiledB: true,
    });
  });
});

