import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws synchronously naming the tool when registering an invalid static inputSchema', () => {
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {count: {type: 'unknown_type'}}};

    expect(() =>
      registry.register({name: 'broken_counter', description: 'Counts items', inputSchema: schema}, async () => '0')
    ).toThrow(/broken_counter/);
  });

  it('reuses the static validator across repeated execute calls without re-reading inputSchema', async () => {
    let schemaReads = 0;
    const schema = {type: 'object', properties: {location: {type: 'string'}}};
    const definition = {
      name: 'get_weather',
      description: 'Get weather',
      get inputSchema() {
        schemaReads += 1;
        return schema;
      },
    };
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(definition, async () => {
      executorCalls += 1;
      return 'sunny';
    });
    const readsAtRegister = schemaReads;

    for (let i = 0; i < 10; i += 1) {
      await registry.execute('get_weather', {location: 'Paris'});
    }

    expect({readsAtRegister, schemaReads, executorCalls}).toEqual({
      readsAtRegister: 1,
      schemaReads: 1,
      executorCalls: 10,
    });
  });

  it('caches compiled validators by schema reference for function-valued tool sources', async () => {
    const trackedA = trackedSchema({city: {type: 'string'}});
    let sourceCalls = 0;
    let currentSchema = trackedA.schema;

    const registry = new ToolRegistry();
    registry.register(
      () => {
        sourceCalls += 1;
        return {
          name: 'dynamic_weather',
          description: 'Dynamic weather tool',
          inputSchema: currentSchema,
        };
      },
      async () => 'ok'
    );
    sourceCalls = 0;

    await registry.execute('dynamic_weather', {city: 'Paris'});
    const readsAAfterFirst = trackedA.getCompileReads();
    await registry.execute('dynamic_weather', {city: 'Lyon'});
    const reusedCachedA = trackedA.getCompileReads() === readsAAfterFirst;
    const trackedB = trackedSchema({zip: {type: 'string'}});
    currentSchema = trackedB.schema;
    await registry.execute('dynamic_weather', {zip: '75001'});

    expect({
      callsDuringExecute: sourceCalls,
      firstCompiledA: readsAAfterFirst > 0,
      reusedCachedA,
      compiledB: trackedB.getCompileReads() > 0,
    }).toEqual({
      callsDuringExecute: 3,
      firstCompiledA: true,
      reusedCachedA: true,
      compiledB: true,
    });
  });

  it('validates input against inputSchema before execution without leaking values or altering valid extra fields', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    setLogger({debug: recordLine, info: recordLine, warn: recordLine, error: recordLine});

    const receivedInputs: Array<Record<string, unknown>> = [];
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'forecast',
        description: 'Forecast weather',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            unit: {type: 'string', enum: ['celsius', 'fahrenheit']},
            options: {
              type: 'object',
              properties: {days: {type: 'number'}},
              required: ['days'],
            },
          },
          required: ['location'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return 'ok';
      }
    );

    const missingResponse = await registry.execute('forecast', {});
    const mismatchResponse = await registry.execute('forecast', {
      location: 'Paris',
      unit: 'kelvin-secret',
      options: {days: 'three-secret'},
    });
    const validInput = {location: 'Paris', unit: 'celsius', options: {days: 3}, extra: 'keep'};
    const validResponse = await registry.execute('forecast', validInput);

    expect({
      missingMentionsLocation: missingResponse.result.includes('location'),
      missingMentionsRequired: /required/i.test(missingResponse.result),
      mismatchMentionsPath: mismatchResponse.result.includes('options.days'),
      mismatchMentionsType: mismatchResponse.result.includes('number'),
      mismatchMentionsEnumField: mismatchResponse.result.includes('unit'),
      leaksOffendingValuesInResult:
        mismatchResponse.result.includes('kelvin-secret') || mismatchResponse.result.includes('three-secret'),
      leaksOffendingValuesInLogs: recordedLogs.some(
        line => line.includes('kelvin-secret') || line.includes('three-secret')
      ),
      receivedInputs,
      validResponse,
    }).toEqual({
      missingMentionsLocation: true,
      missingMentionsRequired: true,
      mismatchMentionsPath: true,
      mismatchMentionsType: true,
      mismatchMentionsEnumField: true,
      leaksOffendingValuesInResult: false,
      leaksOffendingValuesInLogs: false,
      receivedInputs: [validInput],
      validResponse: {result: 'ok'},
    });
  });
});

