function createAjv(): AjvInstance {
  const nodeRequire = createRequire(import.meta.url);
  const loaded = nodeRequire('ajv') as AjvConstructor | {default: AjvConstructor};
  const Ajv = typeof loaded === 'function' ? loaded : loaded.default;
  return new Ajv({
    strict: false,
    validateFormats: false,
    coerceTypes: false,
    useDefaults: false,
    allErrors: true,
  });
}

function compileSchema(ajv: AjvInstance, toolName: string, inputSchema: unknown): CompiledValidator {
  if (!isSchemaObject(inputSchema)) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": expected a JSON Schema object`);
  }
  try {
    return ajv.compile(inputSchema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${reason}`, {cause: error});
  }
}

function isSchemaObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  if ('$async' in value && value.$async !== undefined && value.$async !== false) return false;
  if ('id' in value && value.id !== undefined && typeof value.id !== 'string') return false;
  if ('$id' in value && value.$id !== undefined && typeof value.$id !== 'string') return false;
  if ('$schema' in value && value.$schema !== undefined && typeof value.$schema !== 'string') return false;
  return true;
}

