  /** Validates input against inputSchema (ToolResponse on rejection; specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.resolveValidator(tool);
    if (!validate(input)) {
      const errors = validate.errors ?? [];
      log.warn('tool', 'input validation failed', {
        name,
        failures: errors.map(err => ({field: errorFieldPath(err), constraint: err.keyword})),
      });
      return {result: formatValidationErrors(name, errors)};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function createAjv(): AjvInstance {
  const nodeRequire = createRequire(import.meta.url);
  const Ajv = nodeRequire('ajv') as AjvConstructor;
  return new Ajv({
    strict: false,
    validateFormats: false,
    coerceTypes: false,
    useDefaults: false,
    allErrors: true,
  });
}

function compileSchema(ajv: AjvInstance, toolName: string, inputSchema: unknown): CompiledValidator {
  if (!isSchemaObject(inputSchema)) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": expected a JSON Schema object`);
  }
  try {
    return ajv.compile(inputSchema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${reason}`, {cause: error});
  }
}

function isSchemaObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function formatValidationErrors(toolName: string, errors: AjvValidationError[]): string {
  const details = errors.map(formatValidationError).join('; ');
  return `Invalid input for tool "${toolName}": ${details}`;
}

function formatValidationError(error: AjvValidationError): string {
  const field = errorFieldPath(error);
  if (error.keyword === 'required') return `${field} is required`;
  return `${field} ${error.message ?? error.keyword}`;
}

function errorFieldPath(error: AjvValidationError): string {
  const path = error.instancePath ? error.instancePath.slice(1).replaceAll('/', '.') : '';
  if (error.keyword === 'required') {
    const missing = String(error.params.missingProperty);
    return [path, missing].filter(Boolean).join('.');
  }
  return path || 'input';
}

